from pathlib import Path
import subprocess,json,re
root=Path(__file__).parent
css=(root/'src/styles.css').read_text()
data=json.loads(subprocess.check_output(['node','--input-type=module','-e',"import {FOOD_GROUPS} from './src/data/foods.js'; console.log(JSON.stringify(FOOD_GROUPS));"],cwd=root,text=True))
script=r'''
const GROUPS = __FOODS__;
const GROUP = Object.fromEntries(GROUPS.map(g=>[g.id,g]));
const LABELS = Object.fromEntries(GROUPS.flatMap(g=>g.items.map(it=>[it.id,it.label])));
const KEY='nati-diet-local-demo-v1';
let loaded={}; try{loaded=JSON.parse(localStorage.getItem(KEY)||'{}')}catch(e){}
const state={date:'2026-11-01',page:'meals',month:'2026-11',selectedWeek:'2026-11-01',summaryScope:'week',summaryWeek:'2026-11-01',meals:{},steps:{},weights:{},measurements:{},...loaded};
const SAVE=()=>{try{localStorage.setItem(KEY,JSON.stringify(state));}catch(e){console.warn('Local storage is unavailable',e)}};
const days=Array.from({length:30},(_,i)=>'2026-11-'+String(i+1).padStart(2,'0'));
const weeks=days.filter(d=>d==='2026-11-01'||[5,12,19,26].includes(Number(d.slice(-2))));
const hebDate=(d)=>new Date(d+'T12:00:00').toLocaleDateString('he-IL',{weekday:'long',day:'numeric',month:'long',year:'numeric'});
const esc=(s)=>String(s??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/"/g,'&quot;');
const selected=(meal,key)=>(state.meals[state.date]||{})[meal]?.[key]||'';
function select(group,meal,key,title,optional=false){let value=selected(meal,key);return `<label class="food-field"><span>${title} ${optional?'<small>(רשות)</small>':''}</span><select class="food-select" data-meal="${meal}" data-key="${key}"><option value="">לבחירה מתוך הרשימה...</option>${GROUP[group].items.map(x=>`<option value="${x.id}" ${value===x.id?'selected':''}>${esc(x.label)}</option>`).join('')}</select></label>`}
function veggies(meal,count){return `<div class="veg-fields">${Array.from({length:count},(_,i)=>select('veg',meal,'veg'+(i+1),'ירק '+(i+1),i===3)).join('')}</div>`}
function dual(a,b){return `<div class="dual">${a}${b}</div>`}
function meal(no,title,cal,desc,inner,emoji){const has=!!Object.values((state.meals[state.date]||{})[no]||{}).filter(x=>x&&x!=='carb'&&x!=='fat'&&x!=='bar').length;return `<article class="meal-card"><header class="meal-head"><div class="meal-head-main"><span class="meal-icon">${emoji}</span><div><h3>ארוחה ${no} · ${title}</h3><p>${desc}</p></div></div><div class="meal-head-side"><span class="pill pill-pink">כ־${cal} קק״ל</span>${has?'<span class="save-indicator saved">✓ נשמר מקומית</span>':''}</div></header><div class="meal-body">${inner}<footer class="meal-footer"><span>✓ בחירות אישיות</span><span>דמו · שמירה בדפדפן בלבד</span></footer></div></article>`}
function switches(meal,m){return `<div class="choose-switch"><button data-mode="${meal}" data-to="carb" class="${m==='carb'?'active':''}">מנת פחמימה</button><button data-mode="${meal}" data-to="fat" class="${m==='fat'?'active':''}">2 מנות שומן</button>${meal===3?`<button data-mode="3" data-to="bar" class="${m==='bar'?'active':''}">חטיף חלבון</button>`:''}</div>`}
function stepsContent(){const count=state.steps?.[state.date];const entered=count!==undefined&&count!==null&&count!=='';const n=entered?Number(count):null;const met=entered&&n>=10000;const pct=entered?Math.min(100,Math.max(0,n/100)):0;const fmt=n=>Number(n).toLocaleString('he-IL');return `<section class="steps-card" aria-label="מעקב צעדים יומי"><div class="steps-card-heading"><div class="steps-identity"><span class="steps-icon">👟</span><div><h2>הצעדים שלי היום</h2><p>יעד אישי: 10,000 צעדים בכל יום</p></div></div><span class="steps-status ${!entered?'not-set':met?'success':'pending'}">${!entered?'טרם הוזנו צעדים':met?'✓ עמדת ביעד!':'עדיין לא הגעת ליעד'}</span></div><div class="steps-numbers"><strong>${entered?fmt(n):'—'}</strong><span>מתוך 10,000 צעדים</span></div><div class="steps-progress"><div class="${met?'reached':''}" style="width:${pct}%"></div></div><div class="steps-progress-foot"><span>${Math.round(pct)}% מהיעד</span><span>${!entered?'הזיני את מספר הצעדים שלך':met?`מעבר ליעד ב־${fmt(n-10000)} צעדים`:`נשארו ${fmt(10000-n)} צעדים`}</span></div><div class="steps-summary-cta"><button class="btn btn-outline" data-page="stepsSummary">📈 סיכום צעדים שבועי וחודשי ←</button></div><div class="steps-entry-form"><label for="previewSteps">מספר צעדים בתאריך הנבחר</label><input id="previewSteps" data-steps="1" type="number" inputmode="numeric" min="0" max="200000" step="1" value="${entered?n:''}" placeholder="לדוגמה: 8500"><span class="steps-save-note">✓ השינוי יישמר בדפדפן בלבד</span></div><p class="steps-footnote">הזיני את מספר הצעדים באופן ידני. הנתונים נשמרים עבור היום שנבחר, בדפדפן הנוכחי בלבד.</p></section>`}
function mealContent(){let date=state.date;let m2=((state.meals[date]||{})[2]||{}).mode||'carb',m3=((state.meals[date]||{})[3]||{}).mode||'carb';let n=Object.values(state.meals[date]||{}).filter(o=>Object.values(o).some(v=>v&&v!=='carb'&&v!=='fat'&&v!=='bar')).length;return `<div class="section-head"><div><div class="eyebrow">התפריט היומי שלי</div><h1>היום בוחרת בשבילי 🌷</h1><p>ארבע ארוחות ביום · 1,200 קלוריות לפי התפריט</p></div></div><div class="date-toolbar"><div class="date-info"><span style="font-size:23px">🗓️</span><div><strong>${hebDate(date)}</strong><span>יום ${days.indexOf(date)+1} לתפריט</span></div></div><div class="date-actions"><button class="icon-btn" data-action="prev" ${date==='2026-11-01'?'disabled':''}>❯</button><input type="date" id="daypicker" min="2026-11-01" max="2026-11-30" value="${date}"/><button class="icon-btn" data-action="next" ${date==='2026-11-30'?'disabled':''}>❮</button></div></div><div class="daily-progress"><div class="daily-progress-title"><div><strong>הארוחות שלי</strong><span>${n} מתוך 4 ארוחות עם בחירות</span></div><span class="pill pill-pink">יעד: 1,200 קק״ל</span></div><div class="progress-track"><div style="width:${n*25}%"></div></div></div>${stepsContent()}<div class="meal-stack">
${meal(1,'ארוחת בוקר',200,'פחמימה אחת + חלבון קטן + ירק',`<div class="meal-fields three">${select('carb',1,'carb','פחמימה')}${select('proteinSmall',1,'protein1','חלבון קטן')}${select('veg',1,'veg1','ירק')}</div>`,'☀️')}
${meal(2,'ארוחת צהריים',580,'פחמימה או 2 שומנים + 2 חלבונים גדולים + 3–4 ירקות',switches(2,m2)+`<div class="meal-fields">${m2==='carb'?select('carb',2,'carb','מנת פחמימה'):dual(select('fat',2,'fat1','שומן 1'),select('fat',2,'fat2','שומן 2'))}${dual(select('proteinBig',2,'protein1','חלבון גדול 1'),select('proteinBig',2,'protein2','חלבון גדול 2'))}${veggies(2,4)}</div>`,'🍗')}
${meal(3,'ארוחת ביניים',200,'פחמימה או 2 שומנים + חלבון קטן',switches(3,m3)+(m3==='bar'?`<label class="food-field"><span>חטיף חלבון במקום הארוחה</span><select data-meal="3" data-key="snackbar" class="food-select"><option value="">בחרי חטיף...</option><option value="חטיף חלבון עד 210 קק״ל" ${selected(3,'snackbar')?'selected':''}>חטיף חלבון עד 210 קק״ל</option></select></label>`:dual(m3==='carb'?select('carb',3,'carb','פחמימה'):dual(select('fat',3,'fat1','שומן 1'),select('fat',3,'fat2','שומן 2')),select('proteinSmall',3,'protein1','חלבון קטן'))),'🍓')}
${meal(4,'ארוחת ערב',220,'חלבון קטן + 3–4 ירקות',`<div class="meal-fields">${select('proteinSmall',4,'protein1','חלבון קטן')}${veggies(4,4)}</div>`,'🌙')}</div><div class="notice">ⓘ התחליפים מבוססים על התפריט שסיפקת. יש לאמת מול תזונאית כמויות או קלוריות לא חד־משמעיות.</div>`}
function calendarContent(){let chosen=(state.meals[state.date]||{});return `<div class="section-head"><div><div class="eyebrow">היומן האישי</div><h1>המסע שלי, יום אחרי יום</h1><p>לחצי על תאריך כדי לראות את הבחירות שנשמרו</p></div></div><div class="two-column calendar-layout"><section class="panel calendar-panel"><div class="calendar-head"><div><span class="eyebrow">יומן חודשי</span><h2>נובמבר 2026</h2></div><span class="pill pill-pink">30 ימים</span></div><div class="calendar-grid">${'אבגדהוש'.split('').map(ch=>`<div class="calendar-weekday">${ch}</div>`).join('')}${days.map(d=>{let count=Object.keys(state.meals[d]||{}).length;return `<button class="calendar-day ${state.date===d?'selected':''}" data-date="${d}"><span>${Number(d.slice(-2))}</span><div class="day-dots">${Array.from({length:count},()=>'<i></i>').join('')}</div>${state.steps?.[d]!==undefined&&state.steps[d]!==''?`<span class="calendar-step-badge ${Number(state.steps[d])>=10000?'met':'logged'}">${Number(state.steps[d])>=10000?'✓ צעדים':'👟'}</span>`:''}</button>`}).join('')}</div><div class="calendar-legend">● נקודה לכל ארוחה שמורה · ✓ יעד צעדים הושג</div></section><section class="panel day-recap"><div class="day-recap-head"><span class="eyebrow">סיכום התאריך</span><h2>${hebDate(state.date)}</h2><span class="pill pill-pink">יום ${Number(state.date.slice(-2))} לתפריט</span></div><div class="calendar-steps-recap"><strong>👟 צעדים ביום הזה</strong>${state.steps?.[state.date]===undefined||state.steps[state.date]===''?'<span>טרם הוזנו צעדים</span>':`<span>${Number(state.steps[state.date]).toLocaleString('he-IL')} / 10,000</span><span class="${Number(state.steps[state.date])>=10000?'goal-success':'goal-pending'}">${Number(state.steps[state.date])>=10000?'✓ עמדת ביעד':'עדיין לא הגעת ליעד'}</span>`}</div><div class="recap-list">${[1,2,3,4].map(i=>`<div class="recap-item"><div class="recap-dot">${i}</div><div><strong>ארוחה ${i}</strong><p>${Object.entries(chosen[i]||{}).filter(([key,value])=>key!=='mode'&&value).map(([key,value])=>esc(LABELS[value]||value)).join(' · ')||'לא נבחרו מאכלים'}</p></div></div>`).join('')}</div><button class="btn btn-primary full" data-page="meals">פתיחת התפריט לתאריך הזה ←</button></section></div>`}
function summaryStats(dates){const vals=dates.filter(d=>Object.prototype.hasOwnProperty.call(state.steps||{},d)).map(d=>Number(state.steps[d])).filter(n=>Number.isSafeInteger(n)&&n>=0&&n<=200000);const total=vals.reduce((a,b)=>a+b,0);const good=vals.filter(n=>n>=10000).length;return {total,reported:vals.length,all:dates.length,average:vals.length?Math.round(total/vals.length):null,good,rate:vals.length?Math.round(100*good/vals.length):null};}
const summaryWeekStarts=['2026-11-01','2026-11-08','2026-11-15','2026-11-22','2026-11-29'];
const previewShort=(d)=>new Date(d+'T12:00:00').toLocaleDateString('he-IL',{day:'numeric',month:'numeric'});
function stepsSummaryContent(){const weekly=state.summaryScope==='week';const week=state.summaryWeek||'2026-11-01';const activeDates=weekly?days.slice(Math.max(0,days.indexOf(week)),Math.max(0,days.indexOf(week))+7):days;const info=summaryStats(activeDates);const counts=activeDates.map(d=>state.steps[d]===undefined?0:Number(state.steps[d]));const highest=Math.max(10000,...counts);const fmt=n=>Number(n).toLocaleString('he-IL');const daysCols=activeDates.map(d=>{let entered=state.steps[d]!==undefined&&state.steps[d]!=='';let n=entered?Number(state.steps[d]):0;return `<button class="step-chart-day" data-chart-day="${d}" title="${esc(hebDate(d))}: ${entered?fmt(n)+' צעדים':'אין דיווח'}"><span class="step-chart-value">${entered?fmt(n):'—'}</span><span class="step-chart-bar-wrap"><span class="step-chart-bar ${n>=10000&&entered?'achieved':entered?'not-met':'missing'}" style="height:${entered?Math.max(n===0?2:4,n/highest*100):0}%"></span></span><span class="step-chart-label">${weekly?['א','ב','ג','ד','ה','ו','ש'][new Date(d+'T12:00:00').getDay()]:Number(d.slice(-2))}</span><span class="step-chart-check">${entered&&n>=10000?'✓':' '}</span></button>`}).join('');return `<div class="section-head"><div><div class="eyebrow">סיכום הצעדים שלי</div><h1>כל צעד מצטבר להצלחה 👟</h1><p>ממוצע, סך צעדים, ימי עמידה ביעד וגרף ההתקדמות שלי.</p></div></div><section class="panel steps-summary-toolbar"><div class="steps-period-tabs"><button data-summary-scope="week" class="${weekly?'active':''}">סיכום שבועי</button><button data-summary-scope="month" class="${weekly?'':'active'}">סיכום חודשי</button></div><div class="steps-period-nav">${weekly?`<button class="icon-btn" data-summary-move="prev" ${week==='2026-11-01'?'disabled':''}>❯</button><strong>${previewShort(activeDates[0])} – ${previewShort(activeDates.at(-1))}</strong><button class="icon-btn" data-summary-move="next" ${week==='2026-11-29'?'disabled':''}>❮</button>`:'<strong>נובמבר 2026</strong>'}</div></section><div class="steps-summary-stats"><div class="steps-summary-stat"><span>👟 סה״כ צעדים</span><strong>${fmt(info.total)}</strong><small>בתקופה שנבחרה</small></div><div class="steps-summary-stat"><span>▥ ממוצע יומי</span><strong>${info.average===null?'—':fmt(info.average)}</strong><small>ליום מדווח בלבד</small></div><div class="steps-summary-stat success"><span>✓ ימים ביעד</span><strong>${info.good} <small>מתוך ${info.reported}</small></strong><small>${info.rate===null?'אין דיווחים':info.rate+'% מהימים המדווחים'}</small></div><div class="steps-summary-stat"><span>🗓 ימי דיווח</span><strong>${info.reported} <small>מתוך ${info.all}</small></strong><small>יום חסר אינו נחשב ל־0</small></div></div><section class="panel steps-visual-panel"><div class="steps-chart-head"><div><h2>${weekly?'צעדים לפי יום':'צעדים במהלך החודש'}</h2><p>הקו המקווקו מציין 10,000 צעדים. לחצי על עמודה כדי לפתוח את היום.</p></div><span class="steps-target-chip">יעד: 10,000</span></div>${info.reported===0?'<div class="steps-empty-note">עוד אין צעדים שמורים בתקופה הזו.</div>':''}<div class="steps-chart-scroll"><div class="steps-chart ${weekly?'':'monthly'}" style="--goal-height:${10000/highest*100}%"><div class="steps-chart-plot"><div class="steps-goal-guide"><span>10k</span></div>${daysCols}</div></div></div><div class="steps-chart-legend"><span><i class="swatch achieved"></i> עמדת ביעד</span><span><i class="swatch pending"></i> מתחת ליעד</span><span><i class="swatch missing"></i> לא דווח</span></div></section>${weekly?'':`<section class="panel steps-weekly-breakdown"><div class="steps-chart-head"><div><h2>סיכום לפי שבועות</h2><p>השבוע מתחיל ביום ראשון.</p></div></div><div class="table-scroll"><table class="data-table"><thead><tr><th>שבוע</th><th>סה״כ</th><th>ממוצע</th><th>ימים ביעד</th><th></th></tr></thead><tbody>${summaryWeekStarts.map(start=>{const idx=days.indexOf(start);const wd=days.slice(idx,idx+7);const st=summaryStats(wd);return `<tr><td>${previewShort(wd[0])}–${previewShort(wd.at(-1))}</td><td>${fmt(st.total)}</td><td>${st.average===null?'—':fmt(st.average)}</td><td>${st.good}/${st.reported}</td><td><button class="btn btn-outline steps-week-button" data-week-jump="${start}">הצגת שבוע ←</button></td></tr>`}).join('')}</tbody></table></div></section>`}<section class="panel steps-summary-notes"><p>הממוצע ושיעור ימי ההצלחה מחושבים לפי ימים שבהם הזנת צעדים בלבד. חוסר דיווח אינו כישלון ביעד. בתצוגה הזו הנתונים נשמרים בדפדפן בלבד.</p></section></div>`}
function weightContent(){let entries=Object.entries(state.weights).filter(([d,v])=>v).sort(([a],[b])=>a.localeCompare(b));let base=state.weights['2026-11-01'];let latest=entries.at(-1);let delta=base&&latest?(Number(latest[1])-Number(base)).toFixed(1):'—';return `<div class="section-head"><div><div class="eyebrow">מסע המשקל</div><h1>כל צעד קטן הוא התקדמות</h1><p>שקילת פתיחה ב־1.11.2026, ואחריה בכל יום חמישי</p></div></div><div class="stats-grid"><div class="stat-card"><span>משקל התחלתי</span><strong>${base||'—'} <small>ק״ג</small></strong></div><div class="stat-card"><span>משקל אחרון</span><strong>${latest?latest[1]:'—'} <small>ק״ג</small></strong></div><div class="stat-card highlighted"><span>השינוי מההתחלה</span><strong>${delta} <small>ק״ג</small></strong></div></div><section class="panel"><div class="panel-top"><h2>טבלת השקילות</h2></div><div class="table-scroll"><table class="data-table"><thead><tr><th>תאריך</th><th>משקל בק״ג</th><th>מצב</th></tr></thead><tbody>${weeks.map(d=>`<tr><td>${hebDate(d)}</td><td><input class="table-input" data-weight="${d}" type="number" min="20" max="400" step="0.1" placeholder="למשל 80" value="${state.weights[d]||''}"/></td><td>${state.weights[d]?'✓ נשמר':'—'}</td></tr>`).join('')}</tbody></table></div><p class="fine-print">בדמו הזה השינוי נשמר בדפדפן שלך מיד לאחר הזנת הערך. באתר הענן תופיע שמירה מפורשת, יחד עם גרף.</p></section>`}
const M=[['right_arm','היקף זרוע ימין'],['chest','היקף חזה'],['narrow_waist','היקף בטן (אזור הצר)'],['navel_waist','היקף מותן (2 ס״מ מהטבור)'],['hips','היקף אגן (רגליים צמודות)'],['right_thigh','היקף ירך ימין']];
function measurementsContent(){let record=state.measurements[state.selectedWeek]||{};return `<div class="section-head"><div><div class="eyebrow">מעקב היקפים</div><h1>השינוי שלי בסנטימטרים</h1><p>מדידות שבועיות לפי תאריך</p></div></div><div class="panel"><div class="panel-top"><div><h2>בחרי שבוע למדידה</h2><p>כל שבוע נשמר בנפרד</p></div></div><div class="week-chips">${weeks.map(d=>`<button class="week-chip ${d===state.selectedWeek?'active':''}" data-week="${d}">${d.slice(-2)}.11 ${state.measurements[d]?'✓':''}</button>`).join('')}</div><h3 class="measure-date">${hebDate(state.selectedWeek)}</h3><div class="measure-form">${M.map(([k,label])=>`<label><span>${label}</span><div class="measure-input-wrap"><input type="number" min="10" max="300" step="0.1" data-measure="${k}" value="${record[k]??''}" placeholder="—"/><span>ס״מ</span></div></label>`).join('')}</div><p class="fine-print">הנתונים נשמרים מקומית בדפדפן. גרפי היקפים משותפים זמינים בגרסת הענן.</p></div>`}
function foodsContent(){return `<div class="section-head"><div><div class="eyebrow">המדריך האישי</div><h1>כל התחליפים במקום אחד</h1><p>160 אפשרויות בחירה, מתוך הרשימה שסיפקת</p></div></div><div class="panel food-filters"><div class="food-search"><input id="foodSearch" placeholder="חיפוש מזון..." value="${esc(state.q||'')}"/></div></div><div class="food-sections">${GROUPS.map(g=>{let items=g.items.filter(x=>!state.q||x.label.includes(state.q));if(!items.length)return '';return `<section class="panel food-group"><div class="food-group-heading"><div class="food-group-icon">${g.emoji}</div><div><h2>${g.title}</h2><p>${g.subtitle}</p></div><span class="pill pill-neutral">${items.length} אפשרויות</span></div><div class="food-list">${items.map(x=>`<div class="food-list-item"><span class="food-bullet"></span>${esc(x.label)}</div>`).join('')}</div></section>`}).join('')}</div>`}
function sharingContent(){return `<div class="section-head"><div><div class="eyebrow">פרטיות ושיתוף</div><h1>שיתוף התקדמות לפי הרשאה 🔐</h1><p>בגרסה המחוברת לענן אפשר להזמין משתמשות ולאשר גישה</p></div></div><section class="panel"><div class="empty-state"><span>💌</span><h3>שיתוף בהרשאה אישית</h3><p>בגרסת הענן תוכלי להזמין באמצעות אימייל, לבחור האם לשתף משקל ו/או היקפים, לשנות הרשאות ולבטל שיתוף. בדמו המקומי אין התחברות או שיתוף אמיתי.</p></div></section>`}
function render(){document.querySelectorAll('[data-page]').forEach(x=>x.classList.toggle('active',x.dataset.page===state.page));document.getElementById('topDate').textContent='יום '+(days.indexOf(state.date)+1)+' לתפריט · '+hebDate(state.date);document.getElementById('content').innerHTML=({meals:mealContent,calendar:calendarContent,stepsSummary:stepsSummaryContent,weight:weightContent,measurements:measurementsContent,foods:foodsContent,sharing:sharingContent})[state.page]();}
const root=document.getElementById('shell');
root.addEventListener('click',e=>{const page=e.target.closest('[data-page]');if(page){state.page=page.dataset.page;SAVE();render();window.scrollTo(0,0);return;}const action=e.target.closest('[data-action]');if(action){const i=days.indexOf(state.date)+(action.dataset.action==='next'?1:-1);if(days[i])state.date=days[i];SAVE();render();return;}const day=e.target.closest('[data-date]');if(day){state.date=day.dataset.date;SAVE();render();return;}const scope=e.target.closest('[data-summary-scope]');if(scope){state.summaryScope=scope.dataset.summaryScope;SAVE();render();return;}const prevNext=e.target.closest('[data-summary-move]');if(prevNext){const idx=summaryWeekStarts.indexOf(state.summaryWeek||'2026-11-01')+(prevNext.dataset.summaryMove==='next'?1:-1);if(summaryWeekStarts[idx])state.summaryWeek=summaryWeekStarts[idx];SAVE();render();return;}const weekJump=e.target.closest('[data-week-jump]');if(weekJump){state.summaryScope='week';state.summaryWeek=weekJump.dataset.weekJump;SAVE();render();return;}const chartDay=e.target.closest('[data-chart-day]');if(chartDay){state.date=chartDay.dataset.chartDay;state.page='meals';SAVE();render();return;}const week=e.target.closest('[data-week]');if(week){state.selectedWeek=week.dataset.week;SAVE();render();return;}const mode=e.target.closest('[data-mode]');if(mode){const m=mode.dataset.mode;state.meals[state.date] ||= {};state.meals[state.date][m]={mode:mode.dataset.to};SAVE();render();}});
root.addEventListener('change',e=>{const x=e.target;if(x.id==='daypicker'){state.date=x.value;SAVE();render();return;}if(x.dataset.meal){state.meals[state.date] ||= {};state.meals[state.date][x.dataset.meal] ||= {};state.meals[state.date][x.dataset.meal][x.dataset.key]=x.value;SAVE();render();return;}if(x.dataset.steps){if(x.value!==''&&(!Number.isSafeInteger(Number(x.value))||+x.value<0||+x.value>200000)){alert('הזיני מספר צעדים שלם בין 0 ל־200,000');render();return;}state.steps ||= {};if(x.value==='')delete state.steps[state.date];else state.steps[state.date]=Number(x.value);SAVE();render();return;}if(x.dataset.weight){if(x.value&&(+x.value<20||+x.value>400)){alert('יש להזין משקל תקין');return;}state.weights[x.dataset.weight]=x.value;SAVE();render();return;}if(x.dataset.measure){state.measurements[state.selectedWeek] ||= {};state.measurements[state.selectedWeek][x.dataset.measure]=x.value;SAVE();render();}});
root.addEventListener('input',e=>{if(e.target.id==='foodSearch'){let cur=e.target.selectionStart;state.q=e.target.value;SAVE();render();const search=document.getElementById('foodSearch');search.focus();search.setSelectionRange(cur,cur);}});
render();
'''
script=script.replace('__FOODS__',json.dumps(data,ensure_ascii=False))
html=f'''<!doctype html><html lang="he" dir="rtl"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Nati Diet · תצוגת ניסיון</title><link href="https://fonts.googleapis.com/css2?family=Heebo:wght@400;500;600;700;800&display=swap" rel="stylesheet"><style>{css}</style><style>.preview-ribbon{{background:#5d4454;color:white;padding:8px 20px;font-size:11px;text-align:center;position:sticky;top:0;z-index:30}}.preview-ribbon strong{{color:#ffdbeb}}.sidebar{{top:34px;height:calc(100vh - 34px)}}.calendar-layout .calendar-grid{{min-height:360px}}.app-main{{min-width:0}}@media(max-width:820px){{.sidebar{{top:0;height:100vh}}}}</style></head><body><div id="shell"><div class="preview-ribbon">🌸 <strong>תצוגת ניסיון מקומית:</strong> בחירות נשמרות רק בדפדפן הזה, ללא ענן או שיתוף בין מכשירים.</div><div class="app-shell"><aside class="sidebar"><div class="sidebar-brand"><div class="brandmark">♥</div><div><strong>Nati Diet</strong><span>MY WELLNESS JOURNEY</span></div></div><div class="nav-caption">המסע האישי שלך</div><nav><button data-page="meals" class="nav-item">☀️ התפריט היומי</button><button data-page="calendar" class="nav-item">🗓️ יומן חודשי</button><button data-page="stepsSummary" class="nav-item">👟 סיכום צעדים</button><button data-page="weight" class="nav-item">⚖️ מעקב משקל</button><button data-page="measurements" class="nav-item">📏 מעקב היקפים</button><button data-page="foods" class="nav-item">📖 רשימת תחליפים</button><button data-page="sharing" class="nav-item">🔐 שיתוף התקדמות</button></nav><div class="sidebar-bottom"><div class="sidebar-tip"><span>✦ קטנות ועקביות</span><strong>כל בחירה טובה היא צעד קדימה.</strong><div class="tip-deco">♥</div></div><div class="sidebar-person"><div class="user-avatar">נ</div><div><strong>היומן שלי</strong><small>גרסת תצוגה</small></div></div></div></aside><div class="app-main"><header class="topbar"><div class="topbar-right"><div class="topbar-hello"><span>ברוכה הבאה ♡</span><small id="topDate"></small></div></div><div class="topbar-left"><span class="pill pill-pink">דמו מקומי</span><div class="profile-circle">נ</div></div></header><main class="content-area"><div id="content"></div><footer class="page-footer">Nati Diet · תצוגת ניסיון <span>הנתונים בדפדפן הנוכחי בלבד</span></footer></main></div></div><nav class="bottom-nav"><button data-page="meals">🍽️<span>ארוחות</span></button><button data-page="calendar">🗓️<span>יומן</span></button><button data-page="stepsSummary">👟<span>צעדים</span></button><button data-page="weight">⚖️<span>משקל</span></button><button data-page="measurements">📏<span>היקפים</span></button></nav></div><script>{script}</script></body></html>'''
(root/'preview.html').write_text(html)
print('created',root/'preview.html',len(html),'bytes')
